#!/usr/bin/env python3
import json, sys
sys.path.insert(0, "/tmp")
from probe import probe, extract, dec

TERMS = ["dumb","xterm","xterm-256color","screen","screen-256color",
         "tmux-256color","linux","vt100","ansi","rxvt-unicode-256color",
         "alacritty","xterm-kitty","foot","wezterm"]
COLORTERMS = [None, "truecolor", "24bit", "yes"]

results = {}
for term in TERMS:
    for ct in COLORTERMS:
        env = {"TERM": term}
        if ct: env["COLORTERM"] = ct
        try:
            out, alive = probe(env=env)
            e = dec(extract(out))
            key = f"{term}|CT={ct}"
            results[key] = {"alive": alive, **e, "raw_head": repr(out[:200]) if not e["header"] else None}
            print(f"{key}: {e}", flush=True)
        except Exception as ex:
            results[f"{term}|CT={ct}"] = {"error": str(ex)}
            print(f"{term}|CT={ct}: ERROR {ex}", flush=True)

json.dump(results, open("/tmp/A2_term_matrix.json","w"), indent=1)
print("DONE")

