#!/usr/bin/env python3
"""Task 4: quantizer tables. Usage: t4_table.py xterm-256color|xterm outfile"""
import json, sys, random, re
sys.path.insert(0, "/tmp")
from A2_probe import probe, extract, dec

term = sys.argv[1]
outfile = sys.argv[2]

colors = []
# 216 cube
for r in ("00","33","66","99","cc","ff"):
    for g in ("00","33","66","99","cc","ff"):
        for b in ("00","33","66","99","cc","ff"):
            colors.append(f"#{r}{g}{b}")
# greys
for i in range(0, 256, 17):
    colors.append(f"#{i:02x}{i:02x}{i:02x}")
# 50 random
rnd = random.Random(42)
for _ in range(50):
    colors.append("#%06x" % rnd.randrange(0x1000000))

table = {}
for c in colors:
    env = {"TERM": term, "WALK_MAIN_COLOR": c}
    out, alive = probe(env=env)
    e = dec(extract(out))
    sel = e["selected"][0] if e and e["selected"] else None
    hdr = e["header"][0] if e and e["header"] else None
    trl = e["trailing"][0] if e and e["trailing"] else None
    table[c] = {"selected": sel, "header": hdr, "trailing": trl}
    print(c, sel, hdr, trl, flush=True)

json.dump(table, open(outfile, "w"), indent=1, sort_keys=True)
print("DONE", len(table))

#!/usr/bin/env python3
"""Task 5: env/color-disabling probes + numeric WALK_MAIN_COLOR values."""
import json, sys
sys.path.insert(0, "/tmp")
from A2_probe import probe, extract, dec

results = {}

cases = [
    ("NO_COLOR=1", {"TERM":"xterm-256color","NO_COLOR":"1"}),
    ("NO_COLOR=''", {"TERM":"xterm-256color","NO_COLOR":""}),
    ("CLICOLOR=0", {"TERM":"xterm-256color","CLICOLOR":"0"}),
    ("CLICOLOR_FORCE=1+TERM=dumb", {"TERM":"dumb","CLICOLOR_FORCE":"1"}),
    ("CLICOLOR_FORCE=1", {"TERM":"xterm-256color","CLICOLOR_FORCE":"1"}),
    ("TERM empty", {"TERM":""}),
    ("TERM empty +COLORTERM=truecolor", {"TERM":"","COLORTERM":"truecolor"}),
    ("TERM unset-ish COLORTERM=truecolor", {"TERM":"xterm-256color","COLORTERM":"truecolor","NO_COLOR":"1"}),
]
for name, env in cases:
    try:
        out, alive = probe(env=env)
        results[name] = {"alive": alive, **dec(extract(out)), "raw": repr(out[:400])}
        print(f"{name}: alive={alive} {dec(extract(out))}", flush=True)
    except Exception as ex:
        results[name] = {"error": str(ex)}
        print(f"{name}: ERROR {ex}", flush=True)

# numeric main colors
for n in ["0","1","2","7","8","15","16","17","231","255","256","300","-1","999999"]:
    env = {"TERM":"xterm-256color","WALK_MAIN_COLOR":n}
    try:
        out, alive = probe(env=env)
        results[f"num {n}"] = {"alive": alive, **dec(extract(out))}
        print(f"num {n}: {results[f'num {n}']}", flush=True)
    except Exception as ex:
        print(f"num {n}: ERROR {ex}", flush=True)

# main color fg derivation: light vs dark main colors, truecolor
for c in ["#ffffff","#ffff00","#00ff00","#eeeeee","#777777","#888888","#000000","#0000ff","#808080"]:
    env = {"TERM":"xterm-256color","COLORTERM":"truecolor","WALK_MAIN_COLOR":c}
    out, alive = probe(env=env)
    results[f"fg {c}"] = {"alive": alive, **dec(extract(out))}
    print(f"fg {c}: {results[f'fg {c}']}", flush=True)

json.dump(results, open("/tmp/A2_env_matrix.json","w"), indent=1)
print("DONE")

#!/usr/bin/env python3
"""Task 6: UI screens with/without WALK_MAIN_COLOR."""
import os, sys, json, re
os.makedirs("/tmp/A2_ui", exist_ok=True)
open("/tmp/A2_ui/aaa.txt","w").write("hello\n")
open("/tmp/A2_ui/bbb.txt","w").write("world\n")
os.makedirs("/tmp/A2_ui/sub", exist_ok=True)
sys.path.insert(0, "/tmp")
from A2_probe import probe

def sgrs(out):
    return sorted(set(x.decode() for x in re.findall(rb'\x1b\[([0-9;]+)m', out)))

screens = {
  "baseline": dict(args=[], keys=[(0.2,"q")]),
  "preview": dict(args=["--preview","--with-border"], keys=[(0.3,"q")]),
  "search":  dict(args=[], keys=[(0.2,"/"),(0.3,"q"),(0.2,"q")]),
  "delete":  dict(args=[], keys=[(0.2,"d"),(0.4,"q")]),
  "help":    dict(args=[], keys=[(0.2,"?"),(0.4,"q"),(0.2,"q")]),
}
for wmc in [None, "#ff0000"]:
    for name, kw in screens.items():
        env = {"TERM":"xterm-256color"}
        if wmc: env["WALK_MAIN_COLOR"] = wmc
        try:
            out, alive = probe(env=env, cwd="/tmp/A2_ui", settle=0.6, **kw)
            tag = f"{name}|WMC={wmc}"
            open(f"/tmp/A2_ui_{name}_{'red' if wmc else 'def'}.bin","wb").write(out)
            print(f"== {tag} alive={alive}")
            print("   SGRs:", sgrs(out))
            print(flush=True)
        except Exception as ex:
            print(f"{name}|WMC={wmc}: ERROR {ex}", flush=True)
print("DONE")

